Expression_Obj Parser::parse_value()
{
  lex< css_comments >(false);
  if (lex< ampersand >())
  {
    if (match< ampersand >()) {
      warning("In Sass, \"&&\" means two copies of the parent selector. You probably want to use \"and\" instead.", pstate);
    }
    return SASS_MEMORY_NEW(Parent_Selector, pstate); }

  if (lex< kwd_important >())
  { return SASS_MEMORY_NEW(String_Constant, pstate, "!important"); }

  if (lex< sequence < percentage, lookahead < number > > >())
  { return lexed_percentage(lexed); }

  if (lex< sequence < number, lookahead< sequence < op, number > > > >())
  { return lexed_number(lexed); }

  if (lex< sequence < quoted_string, lookahead < exactly <'-'> > > >())
  { return parse_string(); }

  if (const char* stop = peek< value_schema >())
  { return parse_value_schema(stop); }

  if (lex< quoted_string >())
  { return parse_string(); }

  if (lex< kwd_true >())
  { return SASS_MEMORY_NEW(Boolean, pstate, true); }

  if (lex< kwd_false >())
  { return SASS_MEMORY_NEW(Boolean, pstate, false); }

  if (lex< kwd_null >())
  { return SASS_MEMORY_NEW(Null, pstate); }

  if (lex< identifier >()) {
    return color_or_string(lexed);
  }

  if (lex< percentage >())
  { return lexed_percentage(lexed); }

  if (lex< sequence < alternatives< hex, hex0 >, negate < exactly<'-'> > > >())
  { return lexed_hex_color(lexed); }

  if (lex< hexa >())
  {
    std::string s = lexed.to_string();

    deprecated(
      "The value \""+s+"\" is currently parsed as a string, but it will be parsed as a color in",
      "future versions of Sass. Use \"unquote('"+s+"')\" to continue parsing it as a string.",
      true, pstate
    );

    return SASS_MEMORY_NEW(String_Quoted, pstate, lexed);
  }

  if (lex< sequence < exactly <'#'>, identifier > >())
  { return SASS_MEMORY_NEW(String_Quoted, pstate, lexed); }

  if (lex< sequence< dimension, optional< sequence< exactly<'-'>, lookahead< alternatives < space > > > > > >())
  { return lexed_dimension(lexed); }

  if (lex< sequence< static_component, one_plus< strict_identifier > > >())
  { return SASS_MEMORY_NEW(String_Constant, pstate, lexed); }

  if (lex< number >())
  { return lexed_number(lexed); }

  if (lex< variable >())
  { return SASS_MEMORY_NEW(Variable, pstate, Util::normalize_underscores(lexed)); }

  if (lex< sequence< exactly<'%'>, optional< percentage > > >())
  { return SASS_MEMORY_NEW(String_Constant, pstate, lexed); }

  css_error("Invalid CSS", " after ", ": expected expression (e.g. 1px, bold), was ");

  return 0;
}

BGD_DECLARE(gdImagePtr) gdImageCreateFromGifCtx(gdIOCtxPtr fd)
{
	int BitPixel;
#if 0
	int ColorResolution;
	int Background;
	int AspectRatio;
#endif
	int Transparent = (-1);
	unsigned char buf[16];
	unsigned char c;
	unsigned char ColorMap[3][MAXCOLORMAPSIZE];
	unsigned char localColorMap[3][MAXCOLORMAPSIZE];
	int imw, imh, screen_width, screen_height;
	int useGlobalColormap;
	int bitPixel, i;
	int ZeroDataBlock = FALSE;
	int haveGlobalColormap;

	gdImagePtr im = 0;

	memset(ColorMap, 0, 3 * MAXCOLORMAPSIZE);
	memset(localColorMap, 0, 3 * MAXCOLORMAPSIZE);

	if(!ReadOK(fd, buf, 6)) {
		return 0;
	}

	if(strncmp((char *)buf, "GIF", 3) != 0) {
		return 0;
	}

	if(memcmp((char *)buf + 3, "87a", 3) == 0) {
	} else if(memcmp((char *)buf + 3, "89a", 3) == 0) {
	} else {
		return 0;
	}

	if(!ReadOK(fd, buf, 7)) {
		return 0;
	}

	BitPixel = 2 << (buf[4] & 0x07);
#if 0
	ColorResolution = (int) (((buf[4]&0x70)>>3)+1);
	Background = buf[5];
	AspectRatio = buf[6];
#endif
	screen_width = imw = LM_to_uint(buf[0], buf[1]);
	screen_height = imh = LM_to_uint(buf[2], buf[3]);

	haveGlobalColormap = BitSet(buf[4], LOCALCOLORMAP);
	if(haveGlobalColormap) {
		if(ReadColorMap(fd, BitPixel, ColorMap)) {
			return 0;
		}
	}

	for (;;) {
		int top, left;
		int width, height;

		if(!ReadOK(fd, &c, 1)) {
			return 0;
		}

		if (c == ';') {
			goto terminated;
		}

		if(c == '!') {
			if(!ReadOK(fd, &c, 1)) {
				return 0;
			}

			DoExtension(fd, c, &Transparent, &ZeroDataBlock);
			continue;
		}

		if(c != ',') {
			continue;
		}


		if(!ReadOK(fd, buf, 9)) {
			return 0;
		}

		useGlobalColormap = !BitSet(buf[8], LOCALCOLORMAP);

		bitPixel = 1 << ((buf[8] & 0x07) + 1);
		left = LM_to_uint(buf[0], buf[1]);
		top = LM_to_uint(buf[2], buf[3]);
		width = LM_to_uint(buf[4], buf[5]);
		height = LM_to_uint(buf[6], buf[7]);

		if(((left + width) > screen_width) || ((top + height) > screen_height)) {
			if(VERBOSE) {
				printf("Frame is not confined to screen dimension.\n");
			}
			return 0;
		}

		if(!(im = gdImageCreate(width, height))) {
			return 0;
		}

		im->interlace = BitSet(buf[8], INTERLACE);
		if(!useGlobalColormap) {
			if(ReadColorMap(fd, bitPixel, localColorMap)) {
				gdImageDestroy(im);
				return 0;
			}

			ReadImage(im, fd, width, height, localColorMap, BitSet(buf[8], INTERLACE), &ZeroDataBlock);
		} else {
			if(!haveGlobalColormap) {
				gdImageDestroy(im);
				return 0;
			}

			ReadImage(im, fd, width, height, ColorMap, BitSet(buf[8], INTERLACE), &ZeroDataBlock);
		}

		if(Transparent != (-1)) {
			gdImageColorTransparent(im, Transparent);
		}

		goto terminated;
	}

terminated:
	if(!im) {
		return 0;
	}

	if(!im->colorsTotal) {
		gdImageDestroy(im);
		return 0;
	}

	for(i = im->colorsTotal - 1; i >= 0; i--) {
		if(im->open[i]) {
			im->colorsTotal--;
		} else {
			break;
		}
	}

	return im;
}

